import{_ as l,c as n,o as a,ah as t}from"./chunks/framework.PvdZnrZd.js";const m=JSON.parse('{"title":"Influencer Marketplace","description":"Influencer Marketplace","frontmatter":{"title":"Influencer Marketplace","description":"Influencer Marketplace","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/featured-app/marketplace-other-add-ons/influencer-marketplace.md","filePath":"zenith/featured-app/marketplace-other-add-ons/influencer-marketplace.md"}'),r={name:"zenith/featured-app/marketplace-other-add-ons/influencer-marketplace.md"};function o(i,e,s,c,u,p){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="influencer-marketplace-a-powerful-add-on-for-multivendor-marketplace" tabindex="-1">Influencer Marketplace: A Powerful Add-on for Multivendor Marketplace <a class="header-anchor" href="#influencer-marketplace-a-powerful-add-on-for-multivendor-marketplace" aria-label="Permalink to &quot;Influencer Marketplace: A Powerful Add-on for Multivendor Marketplace&quot;">​</a></h1><p>The <strong>Influencer Marketplace</strong> is an advanced feature app designed to connect sellers with influencers, enabling collaboration to boost product sales through influencer marketing.</p><p>This guide covers the complete workflow, including <strong>installation, configuration, and usage</strong> from <strong>Admin, Seller, and Influencer perspectives</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplaceone.webp" alt="Influencer Marketplace Overview"></p><h2 id="installation-process-overview" tabindex="-1">Installation Process &amp; Overview <a class="header-anchor" href="#installation-process-overview" aria-label="Permalink to &quot;Installation Process &amp; Overview&quot;">​</a></h2><p>To begin using the Influencer Marketplace, install the app:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwo.webp" alt="Installation Process"></p><ul><li>Navigate to the <strong>Multivendor Marketplace App</strong></li><li>Go to the <strong>Featured Apps</strong> section</li><li>Under <strong>Marketplace Other Add-ons</strong>, locate <strong>Influencer Marketplace</strong></li><li>The app is available at a cost of <strong>$10/month</strong></li><li>Click on <strong>Install</strong> to activate the feature</li></ul><p>This app allows sellers to:</p><ul><li>Hire influencers</li><li>Track commissions</li><li>Manage influencer-based promotions</li></ul><h2 id="login-process" tabindex="-1">Login Process <a class="header-anchor" href="#login-process" aria-label="Permalink to &quot;Login Process&quot;">​</a></h2><p>There is <strong>no separate login required</strong> for influencers or sellers.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacethree.webp" alt="Login Process"></p><ul><li>Users can log in through the <strong>same panel used by sellers</strong></li><li>After installation, a new option called <strong>“Influencer”</strong> appears in the dropdown menu</li><li>This option is visible only after installation</li></ul><h2 id="admin-panel-configuration" tabindex="-1">Admin Panel Configuration <a class="header-anchor" href="#admin-panel-configuration" aria-label="Permalink to &quot;Admin Panel Configuration&quot;">​</a></h2><p>The admin manages and controls the influencer marketplace setup.</p><h3 id="influencer-marketplace-configuration" tabindex="-1">Influencer Marketplace Configuration <a class="header-anchor" href="#influencer-marketplace-configuration" aria-label="Permalink to &quot;Influencer Marketplace Configuration&quot;">​</a></h3><h4 id="a-allow-influencers-to-self-register" tabindex="-1">a. Allow Influencers to Self-Register <a class="header-anchor" href="#a-allow-influencers-to-self-register" aria-label="Permalink to &quot;a. Allow Influencers to Self-Register&quot;">​</a></h4><ul><li>Enable this option to allow users to sign up as influencers</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacefour.webp" alt="Self Register"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacefive.webp" alt="Self Register Form"></p><h4 id="b-allow-seller-to-set-commission-rate" tabindex="-1">b. Allow Seller to Set Commission Rate <a class="header-anchor" href="#b-allow-seller-to-set-commission-rate" aria-label="Permalink to &quot;b. Allow Seller to Set Commission Rate&quot;">​</a></h4><ul><li>Sellers can define custom commission rates for each influencer</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacesix.webp" alt="Commission Setting"></p><h4 id="c-commission-bear-by" tabindex="-1">c. Commission Bear By <a class="header-anchor" href="#c-commission-bear-by" aria-label="Permalink to &quot;c. Commission Bear By&quot;">​</a></h4><ul><li>Currently, only the <strong>Seller</strong> option is available</li><li>The seller bears the influencer commission cost</li></ul><h4 id="d-deduct-influencer-commission-on-order-refund" tabindex="-1">d. Deduct Influencer Commission On Order Refund <a class="header-anchor" href="#d-deduct-influencer-commission-on-order-refund" aria-label="Permalink to &quot;d. Deduct Influencer Commission On Order Refund&quot;">​</a></h4><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplaceseven.webp" alt="Refund Deduction"></p><ul><li>If enabled, influencer commission is deducted when an order is refunded</li></ul><h2 id="influencer-marketplace-section" tabindex="-1">Influencer Marketplace Section <a class="header-anchor" href="#influencer-marketplace-section" aria-label="Permalink to &quot;Influencer Marketplace Section&quot;">​</a></h2><h4 id="a-influencer-payment-methods" tabindex="-1">a. Influencer Payment Methods <a class="header-anchor" href="#a-influencer-payment-methods" aria-label="Permalink to &quot;a. Influencer Payment Methods&quot;">​</a></h4><ul><li>Admin can enable payment methods for influencers</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplaceeight.webp" alt="Payment Methods"></p><h4 id="b-manage-influencers" tabindex="-1">b. Manage Influencers <a class="header-anchor" href="#b-manage-influencers" aria-label="Permalink to &quot;b. Manage Influencers&quot;">​</a></h4><ul><li>Add new influencers</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacenine.webp" alt="Add Influencer"></p><ul><li>View associated sellers</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplaceten.webp" alt="Seller Association"></p><ul><li>Check earnings per seller</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplaceeleven.webp" alt="Earnings"></p><ul><li>Edit influencer details</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwelve.webp" alt="Edit Influencer"></p><h2 id="seller-panel-workflow" tabindex="-1">Seller Panel Workflow <a class="header-anchor" href="#seller-panel-workflow" aria-label="Permalink to &quot;Seller Panel Workflow&quot;">​</a></h2><h3 id="hiring-an-influencer" tabindex="-1">Hiring an Influencer <a class="header-anchor" href="#hiring-an-influencer" aria-label="Permalink to &quot;Hiring an Influencer&quot;">​</a></h3><ul><li>Navigate to <strong>Influencer Marketplace → Influencers</strong></li><li>View the list of available influencers</li><li>Click on <strong>three dots (⋮)</strong> → Select <strong>Hire</strong></li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacefifteen.webp" alt="Hire Influencer"></p><ul><li>Set the commission rate while sending the request</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplaceeighteen.webp" alt="Set Commission"></p><h3 id="managing-influencers" tabindex="-1">Managing Influencers <a class="header-anchor" href="#managing-influencers" aria-label="Permalink to &quot;Managing Influencers&quot;">​</a></h3><p>Sellers can:</p><ul><li>Cancel hiring requests</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacenineteen.webp" alt="Cancel Request"></p><ul><li>Terminate hired influencers</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacesixteen.webp" alt="Terminate Influencer"></p><h3 id="viewing-influencer-details" tabindex="-1">Viewing Influencer Details <a class="header-anchor" href="#viewing-influencer-details" aria-label="Permalink to &quot;Viewing Influencer Details&quot;">​</a></h3><p>Sellers can view:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacefourteen.webp" alt="Influencer Details"></p><ul><li>Total earnings</li><li>Due payments</li><li>Payment history</li></ul><h3 id="payments-to-influencers" tabindex="-1">Payments to Influencers <a class="header-anchor" href="#payments-to-influencers" aria-label="Permalink to &quot;Payments to Influencers&quot;">​</a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwenty.webp" alt="Payments"></p><ul><li>Use configured payment methods (if available)</li><li>Or: <ul><li>Make manual payments</li><li>Record transactions within the app</li></ul></li></ul><h3 id="order-based-commission-management" tabindex="-1">Order-Based Commission Management <a class="header-anchor" href="#order-based-commission-management" aria-label="Permalink to &quot;Order-Based Commission Management&quot;">​</a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/orderview.webp" alt="Order Commission"></p><ul><li>Go to <strong>Order Listing</strong></li><li>View <strong>Influencer Earnings</strong></li><li>Accept or reject commission per order</li></ul><p><strong>Note:</strong> This option is available only after the order is <strong>fulfilled</strong>.</p><h2 id="influencer-panel-dashboard" tabindex="-1">Influencer Panel / Dashboard <a class="header-anchor" href="#influencer-panel-dashboard" aria-label="Permalink to &quot;Influencer Panel / Dashboard&quot;">​</a></h2><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwentyone.webp" alt="Influencer Dashboard"></p><h3 id="sellers-section" tabindex="-1">Sellers Section <a class="header-anchor" href="#sellers-section" aria-label="Permalink to &quot;Sellers Section&quot;">​</a></h3><ul><li>View seller requests</li><li>Accept or reject requests</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwentytwo.webp" alt="Requests"></p><ul><li>View seller details</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwentythree.webp" alt="Seller Details"></p><ul><li>Track earnings (Total, Paid, Due)</li></ul><h3 id="payment-methods" tabindex="-1">Payment Methods <a class="header-anchor" href="#payment-methods" aria-label="Permalink to &quot;Payment Methods&quot;">​</a></h3><ul><li>Choose from admin-enabled methods</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwentysix.webp" alt="Payment Config"></p><ul><li>Configure to receive payments</li></ul><h3 id="payouts" tabindex="-1">Payouts <a class="header-anchor" href="#payouts" aria-label="Permalink to &quot;Payouts&quot;">​</a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwentyfour.webp" alt="Payouts"></p><ul><li>Track total earnings</li><li>View payout history</li></ul><h3 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/influencermarketplacetwentyfive.webp" alt="Profile"></p><ul><li>Edit personal details</li><li>Update profile information</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The <strong>Influencer Marketplace add-on</strong> enhances your multivendor store by enabling seamless collaboration between <strong>sellers and influencers</strong>.</p><p>With:</p><ul><li>Flexible commission settings</li><li>Transparent earnings tracking</li><li>Easy payment management</li></ul><p>It creates a <strong>win-win ecosystem</strong> for all parties.</p><p>Whether you&#39;re an <strong>admin</strong>, <strong>seller</strong>, or <strong>influencer</strong>, this feature simplifies the entire process efficiently.</p><h2 id="need-help" tabindex="-1">Need Help? <a class="header-anchor" href="#need-help" aria-label="Permalink to &quot;Need Help?&quot;">​</a></h2><p>If you face any issues:</p><ul><li>Email: <strong><a href="mailto:support@webkul.com" target="_blank" rel="noreferrer">support@webkul.com</a></strong></li><li>Or create a ticket at <strong>Webkul UV Desk</strong></li></ul>',92)])])}const h=l(r,[["render",o]]);export{m as __pageData,h as default};
